const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const somalia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Somalia'));
  const geometry = somalia.geometry();

  const april2019Start = '2019-04-01';
  const april2019End = '2019-04-30';

  // Average April conditions exclude 2019 to ensure independence. SMAP data starts March 31, 2015.
  const avgAprilStart = '2015-04-01';
  const avgAprilEnd = '2018-04-30'; // Up to 2018 for the average

  // 2. Data Acquisition & Pre-processing
  const smap = ee.ImageCollection('NASA/SMAP/SPL3SMP_E/003');

  // Function to mask invalid soil moisture values
  // SMAP soil_moisture_error_code: 0 is good quality. surface_soil_moisture is -9999 for masked values.
  const maskSmap = function(image) {
    const sm = image.select('surface_soil_moisture');
    const errorCode = image.select('soil_moisture_error_code');
    // Mask out values that are -9999, negative, or have error codes indicating bad quality
    return sm.updateMask(sm.gt(0).and(sm.lt(1)).and(errorCode.eq(0)));
  };

  // Process 2019 data
  let smap2019 = smap.filterDate(april2019Start, april2019End)
                     .filterBounds(geometry)
                     .map(maskSmap);

  if (smap2019.size().getInfo() === 0) {
    console.log("No SMAP images found for April 2019 in Somalia.");
    console.log("C1");
    return;
  }

  // Process average April data
  // Filter for April months across multiple years
  let smapAvg = smap.filterDate(avgAprilStart, avgAprilEnd)
                    .filter(ee.Filter.calendarRange(4, 4, 'month')) // Only April
                    .filterBounds(geometry)
                    .map(maskSmap);

  if (smapAvg.size().getInfo() === 0) {
    console.log("No SMAP images found for average April conditions in Somalia.");
    console.log("C1");
    return;
  }

  // Create composite images (mean)
  const meanSmap2019 = smap2019.mean().select('surface_soil_moisture');
  const meanSmapAvg = smapAvg.mean().select('surface_soil_moisture');

  // 3. Calculation of mean soil moisture
  const scale = 9000; // SMAP native resolution is 9km

  const reducer = ee.Reducer.mean().setOutputs(['mean_soil_moisture']);
  const countReducer = ee.Reducer.count().setOutputs(['pixel_count']);

  // Reduce for 2019
  const regionStats2019 = meanSmap2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });
  const val2019 = regionStats2019.get('mean_soil_moisture').getInfo();
  const count2019 = regionStats2019.get('surface_soil_moisture_count').getInfo();

  // Reduce for average April
  const regionStatsAvg = meanSmapAvg.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });
  const valAvg = regionStatsAvg.get('mean_soil_moisture').getInfo();
  const countAvg = regionStatsAvg.get('surface_soil_moisture_count').getInfo();

  // 4. Validation & Final Answer
  if (count2019 === 0) {
    console.log(`April 2019: No valid pixels remaining after masking for Somalia.`);
    console.log("C2");
    return;
  }
  if (countAvg === 0) {
    console.log(`Average April: No valid pixels remaining after masking for Somalia.`);
    console.log("C2");
    return;
  }

  if (val2019 === null || isNaN(val2019) || valAvg === null || isNaN(valAvg)) {
    console.log("Calculation resulted in invalid (null/NaN) soil moisture values.");
    console.log("C3");
    return;
  }

  console.log(`SMAP images (April 2019): ${smap2019.size().getInfo()}`);
  console.log(`SMAP images (Avg April): ${smapAvg.size().getInfo()}`);
  console.log(`April 2019 Mean Soil Moisture: ${val2019.toFixed(4)} m³/m³ (Pixels: ${count2019})`);
  console.log(`Average April Mean Soil Moisture: ${valAvg.toFixed(4)} m³/m³ (Pixels: ${countAvg})`);

  if (val2019 < valAvg) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
